// Two doors into this workflow: the webhook (real Daystar delivery) and the
// manual trigger (dry run). Collapse both to { filename, batch } so nothing
// downstream has to know which one fired.
const SYNTHETIC_FILENAME = 'daystar-2026-08-12-social.json';
const SYNTHETIC_BATCH = {
  batch_id: 'daystar-2026-08-12-social',
  submitted_at: '2026-08-12T09:00:00Z',
  readings: [
    { zone_id: 'westlands', indicator: 'healthcare_access', value: 72.4, unit: 'index_0_100', observed_at: '2026-08-12T09:00:00Z', field_verified: true, centroid: { lon: 36.8048, lat: -1.2673 }, source: 'daystar' },
    { zone_id: 'westlands', indicator: 'education_access', value: 68.1, unit: 'index_0_100', observed_at: '2026-08-12T09:00:00Z', field_verified: false, centroid: { lon: 36.8048, lat: -1.2673 }, source: 'daystar' },
    { zone_id: 'starehe', indicator: 'digital_connectivity', value: 41.6, unit: 'mbps', observed_at: '2026-08-12T09:00:00Z', field_verified: false, centroid: { lon: 36.83, lat: -1.28 }, source: 'daystar' },
    { zone_id: 'kibra', indicator: 'healthcare_access', value: 44.9, unit: 'index_0_100', observed_at: '2026-08-12T09:00:00Z', field_verified: true, centroid: { lon: 36.78, lat: -1.313 }, source: 'daystar' }
  ]
};

const out = [];
for (const item of $input.all()) {
  const payload = item.json.body ?? item.json;
  const filename = payload.filename ?? payload.file_name ?? null;
  const batch = payload.batch ?? (Array.isArray(payload.readings) ? payload : null);
  if (filename && batch) {
    out.push({ json: { filename, batch, dry_run: false } });
  }
}

if (out.length === 0) {
  out.push({ json: { filename: SYNTHETIC_FILENAME, batch: SYNTHETIC_BATCH, dry_run: true } });
}

return out;

// The filename is the only metadata available before the file is opened, so
// it is a hard gate — see the "Drop filename convention" section of
// docs/data/daystar-indicator-spec.md. A drop that fails here is
// quarantined and never reaches the ingestion service.
const INDICATORS = [
  'healthcare_access', 'education_access', 'digital_connectivity',
  'crime_rates', 'emergency_response_access', 'disaster_exposure',
  'population_density', 'congestion', 'housing_pressure',
  'road_quality', 'energy_reliability', 'food_risk', 'waste_management'
];
const GROUPS = ['social', 'safety', 'density', 'infra'];
const MAX_ROWS = 5000;

function isRealDate(segment) {
  const [y, m, d] = segment.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

return $input.all().map((item) => {
  const { filename, batch, dry_run } = item.json;
  const reasons = [];
  let observedDate = null;
  let scope = null;
  let seq = null;

  if (!filename) {
    reasons.push('filename missing');
  } else if (!filename.endsWith('.json')) {
    reasons.push('extension must be .json — the batch envelope is JSON, not CSV');
  } else {
    const match = /^daystar-(\d{4}-\d{2}-\d{2})-(.+)\.json$/.exec(filename);
    if (!match) {
      reasons.push('expected daystar-<YYYY-MM-DD>-<scope>[-<seq>].json');
    } else {
      observedDate = match[1];
      let rest = match[2];
      const seqMatch = /^(.+)-(\d{2,})$/.exec(rest);
      if (seqMatch) {
        rest = seqMatch[1];
        seq = seqMatch[2];
      }
      scope = rest;
      if (!isRealDate(observedDate)) {
        reasons.push(`date segment ${observedDate} is not a real calendar date`);
      }
      if (!GROUPS.includes(scope) && !INDICATORS.includes(scope)) {
        reasons.push(`unknown scope '${scope}' — expected a pillar group (${GROUPS.join(', ')}) or one of the 13 indicator keys`);
      }
    }
  }

  const readings = Array.isArray(batch?.readings) ? batch.readings : null;
  if (!readings) {
    reasons.push('batch has no readings array');
  } else if (readings.length === 0) {
    reasons.push('batch is empty');
  } else if (readings.length > MAX_ROWS) {
    // Mirror the ingestion row cap so an oversized drop is quarantined with an
    // actionable message instead of bouncing back as a bare 413.
    reasons.push(`batch has ${readings.length} rows, over the ${MAX_ROWS}-row cap — chunk it with a -NN suffix`);
  }

  return {
    json: {
      filename,
      batch,
      dry_run,
      valid: reasons.length === 0,
      reasons,
      stem: filename ? filename.replace(/\.json$/, '') : null,
      observed_date: observedDate,
      scope,
      seq
    }
  };
});

// Turn the ingestion receipt into one line a human in #data-feeds can act on.
// Item order is 1:1 with Validate Filename because the HTTP node emits one
// response per input item.
const INDICATOR_COUNT = 13;

return $input.all().map((item, index) => {
  const response = item.json;
  const status = response.statusCode ?? 0;
  const receipt = response.body ?? {};
  const drop = $('Validate Filename').all()[index].json;
  const readings = drop.batch?.readings ?? [];

  // The receipt echoes every rejected row in full, so the indicators that
  // actually landed are the submitted ones minus the rejected ones.
  const rejections = receipt.rejections ?? [];
  const rejectedRows = new Set(rejections.map((r) => `${r.zone_id}|${r.indicator}|${r.observed_at}`));
  const active = new Set(
    readings
      .filter((r) => !rejectedRows.has(`${r.zone_id}|${r.indicator}|${r.observed_at}`))
      .map((r) => r.indicator)
  );

  const ok = status >= 200 && status < 300;
  const duplicate = receipt.duplicate === true;
  const failedZones = (receipt.forwarded ?? []).filter((f) => !f.ok).map((f) => f.zone_id);

  const icon = duplicate ? ':repeat:' : ok ? ':white_check_mark:' : ':rotating_light:';
  const lines = [`${icon} *Daystar drop* \`${drop.filename}\`${drop.dry_run ? ' _(dry run)_' : ''}`];

  if (duplicate) {
    lines.push(`Already ingested — replay of \`${receipt.payload_hash}\`, nothing re-counted.`);
  } else if (!ok) {
    lines.push(`Ingestion answered *${status}* — ${receipt.detail ?? receipt.title ?? 'no detail returned'}`);
  }

  lines.push(`Accepted *${receipt.accepted ?? 0}* · rejected *${receipt.rejected ?? 0}* · anomalies *${(receipt.anomalies ?? []).length}*`);
  lines.push(`*${active.size} of ${INDICATOR_COUNT}* indicators active in this drop`);

  if (failedZones.length) {
    lines.push(`:warning: Laravel forward failed for: ${failedZones.join(', ')}`);
  }
  if (rejections.length) {
    const sample = rejections.slice(0, 3).map((r) => `\`${r.zone_id}/${r.indicator}\` — ${r._reject_reason}`);
    lines.push(`First rejections: ${sample.join(' · ')}`);
  }

  return {
    json: {
      text: lines.join('\n'),
      status,
      duplicate,
      active_indicators: active.size,
      payload_hash: receipt.payload_hash ?? null,
      quarantined: false
    }
  };
});

// A quarantined drop never reaches the ingestion service, so there is no
// receipt to summarise — the filename reasons are the whole message.
return $input.all().map((item) => {
  const drop = item.json;
  const lines = [
    `:no_entry: *Daystar drop quarantined* \`${drop.filename ?? '(no filename)'}\`${drop.dry_run ? ' _(dry run)_' : ''}`,
    'Nothing was forwarded to the ingestion service.',
    ...drop.reasons.map((reason) => `• ${reason}`),
    'Convention: `daystar-<YYYY-MM-DD>-<scope>[-<seq>].json` — docs/data/daystar-indicator-spec.md'
  ];

  return { json: { text: lines.join('\n'), quarantined: true, filename: drop.filename ?? null } };
});
